const pngDataUrl = {
    name: 'png-dataurl',
    load(id: string) {
        if (id.endsWith('.png')) {
            const base64 = fs.readFileSync(id).toString('base64');
            return `export default "data:image/png;base64,${base64}";`;
        }
        return null;
    }
};
